//! The web-platform-tests URL data (`url/resources/*.json` of
//! https://github.com/web-platform-tests/wpt, 3-Clause BSD License,
//! copyright the web-platform-tests contributors; IdnaTestV2.json is
//! generated by WPT from Unicode's IdnaTestV2.txt, Unicode License),
//! vendored in `tests/fixtures/wpt/` (with WPT's LICENSE.md) as of WPT
//! commit c48d587 and checked by SHA-256 below.
//!
//! goro follows PHP 8.5, whose WHATWG parser implements an earlier state of
//! the URL Standard and of UTS #46 processing. These tests check that every
//! WPT expectation holds except where PHP 8.5 gives another result, and that
//! in those cases goro gives PHP's (the PHP 8.5 results are the
//! `whatwg_php85.txt` fixture, recorded over the same inputs).

mod common;
use common::json::{self, Json};
use common::*;
use goro_ext_uri::whatwg::Url;
use std::collections::HashMap;

const FILES: &[(&str, &str)] = &[
    (
        "urltestdata.json",
        "81e85fd3c199c08ef9c34cf651b3580eeedd080316493bfaf277a6b5ff8cf652",
    ),
    (
        "toascii.json",
        "644eba9d5b593df8095cfa307222f3014542ff9cc02d555f8e5660059d80470f",
    ),
    (
        "IdnaTestV2.json",
        "84de621e5239676e59e5a3e68ef3e2b1acde9da5480a633d2ef446ef03238b76",
    ),
    (
        "setters_tests.json",
        "62e4b14bdaddd66b0f7d99bf066aed1c4a588667f4aa97bf26da212134fc24bf",
    ),
];

fn load(name: &str) -> Json {
    let path = format!("{}/tests/fixtures/wpt/{name}", env!("CARGO_MANIFEST_DIR"));
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let want = FILES.iter().find(|(n, _)| *n == name).unwrap().1;
    let got: String = purecrypto::hash::sha256(&data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    assert_eq!(got, want, "{name}: unexpected SHA-256");
    json::parse(&data)
}

/// The inputs of urltestdata.json where PHP 8.5 (and goro) differ from the
/// WPT expectation, with PHP's behaviour (observed on PHP 8.5).
const URLTESTDATA_PHP_DEVIATIONS: &[&str] = &[
    // A "%2e%2e" segment followed by '?' takes it as a separator.
    "https://example.com/aaa/bbb/%2e%2e?query",
    // Spaces at the end of an opaque path stay as they are.
    "non-special:opaque  ?hi",
    "non-special:opaque  #hi",
    "non-special:opaque \t\t  \t#hi",
    "non-special:opaque \t\t  #hi",
    "non-special:opaque\t\t  \r #hi",
    // `xn--` labels that are not valid Punycode, or decode to nothing,
    // fail (PHP's UTS #46 processing).
    "http://a.b.c.xn--pokxncvks",
    "http://10.0.0.xn--pokxncvks",
    "http://a.b.c.XN--pokxncvks",
    "http://a.b.c.Xn--pokxncvks",
    "http://10.0.0.XN--pokxncvks",
    "http://10.0.0.xN--pokxncvks",
    "file://xn--/p",
    "https://xn--/",
    // '^' is not in the path percent-encode set.
    "foo://host/ !\"$%&'()*+,-./:;<=>@[\\]^_`{|}~",
    "wss://host/ !\"$%&'()*+,-./:;<=>@[\\]^_`{|}~",
];

fn opt(u: Option<&[u8]>) -> &[u8] {
    u.unwrap_or(b"")
}

/// The WPT view of a URL (the URL API's attributes).
fn attrs(u: &Url) -> Vec<(&'static str, Vec<u8>)> {
    let host = opt(u.ascii_host()).to_vec();
    let mut hostport = host.clone();
    if let Some(p) = u.port() {
        hostport.push(b':');
        hostport.extend_from_slice(p.to_string().as_bytes());
    }
    let pre = |p: u8, v: Option<&[u8]>| match v {
        Some(v) if !v.is_empty() => [&[p][..], v].concat(),
        _ => Vec::new(),
    };
    vec![
        ("href", u.to_ascii_string().to_vec()),
        ("protocol", [u.scheme(), b":"].concat()),
        ("username", opt(u.username()).to_vec()),
        ("password", opt(u.password()).to_vec()),
        ("host", hostport),
        ("hostname", host),
        (
            "port",
            u.port().map_or(Vec::new(), |p| p.to_string().into_bytes()),
        ),
        ("pathname", u.path().to_vec()),
        ("search", pre(b'?', u.query())),
        ("hash", pre(b'#', u.fragment())),
    ]
}

fn parse_with(input: &[u8], base: Option<&[u8]>) -> Option<Url> {
    let b = match base {
        Some(b) => Some(Url::parse(b, None).ok()?.0),
        None => None,
    };
    Url::parse(input, b.as_ref()).ok().map(|(u, _)| u)
}

#[test]
fn wpt_urltestdata() {
    let data = load("urltestdata.json");
    let Json::Arr(cases) = data else { panic!() };
    let mut deviations: Vec<String> = Vec::new();
    let mut total = 0;
    for c in &cases {
        let Json::Obj(_) = c else { continue };
        total += 1;
        let input = c.get("input").unwrap().str().unwrap();
        let base = c.get("base").and_then(Json::str);
        let got = parse_with(input, base);
        let want_failure = c.get("failure") == Some(&Json::Bool(true));
        let ok = match (&got, want_failure) {
            (None, true) => true,
            (Some(_), true) | (None, false) => false,
            (Some(u), false) => attrs(u).iter().all(|(k, v)| {
                c.get(k)
                    .and_then(Json::str)
                    .is_none_or(|w| w == v.as_slice())
            }),
        };
        if !ok {
            deviations.push(String::from_utf8_lossy(input).into_owned());
        }
    }
    deviations.sort();
    deviations.dedup();
    let mut expected: Vec<String> = URLTESTDATA_PHP_DEVIATIONS
        .iter()
        .map(|s| s.to_string())
        .collect();
    expected.sort();
    assert_eq!(
        deviations, expected,
        "WPT urltestdata deviations ({total} cases)"
    );
}

/// ASCII hosts PHP 8.5 gives for `https://<input>/x` (None: failure), from
/// the fixture.
fn php85_hosts() -> HashMap<Vec<u8>, Option<Vec<u8>>> {
    let mut m = HashMap::new();
    for f in fixture("whatwg_php85.txt") {
        if f[2] != "-" || f[3] == "BASEFAIL" {
            continue;
        }
        let host = if f[3] == "NULL" {
            None
        } else {
            let field = f[3].split('|').nth(3).unwrap();
            Some(unq(field))
        };
        m.insert(unhex(&f[1]), host);
    }
    m
}

fn unq(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 1;
    while i < b.len() - 1 {
        if b[i] == b'\\' {
            out.push(u8::from_str_radix(&s[i + 2..i + 4], 16).unwrap());
            i += 4;
        } else {
            out.push(b[i]);
            i += 1;
        }
    }
    out
}

fn host_cases(file: &str) {
    let data = load(file);
    let Json::Arr(cases) = data else { panic!() };
    let php = php85_hosts();
    let (mut total, mut as_wpt, mut as_php) = (0, 0, 0);
    for c in &cases {
        let Json::Obj(_) = c else { continue };
        total += 1;
        let input = c.get("input").unwrap().str().unwrap();
        let want: Option<Vec<u8>> = c.get("output").and_then(Json::str).map(<[u8]>::to_vec);
        let url = [b"https://".as_slice(), input, b"/x"].concat();
        let got = parse_with(&url, None).map(|u| opt(u.ascii_host()).to_vec());
        if got == want {
            as_wpt += 1;
            continue;
        }
        let p = php
            .get(&url)
            .unwrap_or_else(|| panic!("{} not in the PHP 8.5 fixture", show(&url)));
        assert_eq!(
            &got,
            p,
            "{file}: {} differs from WPT and from PHP 8.5",
            show(input)
        );
        as_php += 1;
    }
    eprintln!("{file}: {total} cases, {as_wpt} as WPT expects, {as_php} as PHP 8.5 gives instead");
}

#[test]
fn wpt_idna_test_v2() {
    host_cases("IdnaTestV2.json");
}

#[test]
fn wpt_toascii() {
    host_cases("toascii.json");
}
